def solution(a, b, n):
    """
    Find the first non-negative integer pair (x, y) such that a*x + b*y = n.
    Returns (x, y) or None if no such pair exists.
    """
    for x in range(n // a + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return None

