def substract_elements(t1, t2):
    """
    Subtract elements of two nested tuples element-wise.

    Rules:
    - If both elements are tuples, recurse element-wise.
    - If both elements are numbers, subtract.
    - If tuples have different lengths, treat missing elements as 0.
    - If types mismatch or non-numeric non-tuple elements are encountered, raise ValueError.

    Args:
        t1, t2: nested tuples (or numbers)

    Returns:
        nested tuple (or number) with element-wise subtraction: t1 - t2
    """
    # Helper to check if an object is a tuple
    def is_tuple(obj):
        return isinstance(obj, tuple)

    # Helper to check if an object is a number (int or float)
    def is_number(obj):
        return isinstance(obj, (int, float))

    # If both are tuples
    if is_tuple(t1) and is_tuple(t2):
        max_len = max(len(t1), len(t2))
        result = []
        for i in range(max_len):
            e1 = t1[i] if i < len(t1) else 0
            e2 = t2[i] if i < len(t2) else 0
            result.append(substract_elements(e1, e2))
        return tuple(result)

    # If both are numbers
    elif is_number(t1) and is_number(t2):
        return t1 - t2

    # If one is tuple and other is number
    elif is_tuple(t1) and is_number(t2):
        # subtract t2 from each element of t1 recursively
        return tuple(substract_elements(e, t2) for e in t1)

    elif is_number(t1) and is_tuple(t2):
        # subtract each element of t2 from t1 recursively
        return tuple(substract_elements(t1, e) for e in t2)

    else:
        raise ValueError(f"Unsupported element types for subtraction: {type(t1)} and {type(t2)}")


