def get_noOfways(n: int) -> int:
    if n == 0:
        return 0
    # Assuming the problem is to find number of ways to reach step n (classic staircase problem)
    # Let's implement a solution for that:
    if n == 1:
        return 1
    if n == 2:
        return 2

    dp = [0] * (n + 1)
    dp[1], dp[2] = 1, 2

    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[n]

def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    s = str(num)

    # If all digits are 9, the next palindrome is 10..01 (e.g. 999 -> 1001)
    if is_all_nines(s):
        return num + 2  # For 9 -> 11, for 99 -> 101, for 999 -> 1001 etc.

    length = len(s)
    half = length // 2
    left = s[:half]
    middle = s[half] if length % 2 != 0 else ''
    right = s[half + (1 if length % 2 != 0 else 0):]

    # Form a palindrome by mirroring the left side to right
    if length % 2 == 0:
        palindrome = left + left[::-1]
    else:
        palindrome = left + middle + left[::-1]

    palindrome_num = int(palindrome)

    # If palindrome is not strictly greater, increment the middle part and mirror again
    if palindrome_num <= num:
        if length % 2 == 0:
            # Increment the left part and mirror
            incremented_left = str(int(left) + 1)
            # Handle case when increment changes length (like 99 -> 100)
            if len(incremented_left) > len(left):
                # This means palindrome length increases by 1
                # e.g. 9999 -> after increment left=100, palindrome=100001
                return int(incremented_left + incremented_left[:-1][::-1])
            palindrome = incremented_left + incremented_left[::-1]
        else:
            # Increment the middle digit(s)
            middle_num = int(left + middle)
            middle_num += 1
            middle_str = str(middle_num)
            # If length changes after increment (like 999 -> 1000)
            if len(middle_str) > len(left + middle):
                # e.g. 999 -> 1000, palindrome length increases by 1
                return int(middle_str + middle_str[:-1][::-1])
            palindrome = middle_str + middle_str[:-1][::-1]

        palindrome_num = int(palindrome)

    return palindrome_num

