def tuple_to_set(tuples):
    """
    Transforms a sequence of tuples into a set containing all elements.
    Nested tuples inside the input tuples are flattened into individual elements.
    Duplicates are automatically removed due to the nature of sets.

    Args:
        tuples (iterable of tuples): Input tuples which may contain nested tuples.

    Returns:
        set: A set of all individual elements from the input tuples.
    """
    result = set()

    def flatten(item):
        if isinstance(item, tuple):
            for subitem in item:
                flatten(subitem)
        else:
            result.add(item)

    for t in tuples:
        flatten(t)

    return result

