    s = str(n)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # For all 9's, next palindrome is 10..01 (length + 1 digits)
        return n + 2

    def create_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    mid = length // 2

    # Split the number into two halves
    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    pal_candidate = create_palindrome(left, odd_length)

    if pal_candidate > n:
        return pal_candidate

    # Increment the left part and create palindrome again
    # Convert to int, increment and back to string
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # If length changed due to increment (e.g., 99 -> 100), adjust
