def dict_depth(d):
    if not isinstance(d, dict):
        return 0

    if not d:
        # Empty dict contributes depth 1
        return 1

    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
        elif isinstance(v, (list, tuple)):
            depth = 1 + max((dict_depth(i) for i in v if isinstance(i, dict)), default=0)
        else:
            depth = 0
        if depth > max_depth:
            max_depth = depth
    return max_depth

