def remove_column(matrix: List[List[Any]], col_idx: int) -> List[List[Any]]:
    if not matrix:
        # Empty matrix, return as is
        return []

    row_length = len(matrix[0])

    # Validate all rows have the same length
    for row in matrix:
        if len(row) != row_length:
            raise ValueError("All rows must have the same length")

    # If rows are empty, just return the matrix as is (no columns to remove)
    if row_length == 0:
        return matrix.copy()

    if not (0 <= col_idx < row_length):
        raise IndexError("Column index out of range")

    # Remove the column at col_idx from each row
    result = [row[:col_idx] + row[col_idx+1:] for row in matrix]

    # Validate that all rows in result have the same length after removal
    new_length = row_length - 1
    for row in result:
        if len(row) != new_length:
            raise ValueError("Rows have inconsistent length after column removal")

    return result

