            # Previous element must be <= x//2 (since current element >= 2 * previous)
            max_prev = x // 2
            # Sum all dp[i-1][prev] where prev <= max_prev
            # To optimize, we can keep prefix sums
            # But for clarity, do direct summation here
            total = 0
            for prev in range(1, max_prev+1):
                total += dp[i-1][prev]
            dp[i][x] = total

    # Total sequences of length n is sum over all ending elements
    return sum(dp[n][1:m+1])

