def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of valid sequences of length i ending with element x
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1 can be any element from 1 to m
    for x in range(1, m + 1):
        dp[1][x] = 1

    for i in range(2, n + 1):
        for x in range(1, m + 1):
            # previous element y must satisfy:
            # x >= 2*y  => y <= x//2
            # and y in [1..m]
            limit = x // 2
            if limit == 0:
                # no valid previous element
                dp[i][x] = 0
            else:
                # sum all dp[i-1][y] for y in [1..limit]
                dp[i][x] = sum(dp[i-1][1:limit+1])

    # total sequences of length n
    return sum(dp[n][1:])

