def order_by_points(nums):
    def digit_sum(num):
        s = str(num)
        total = 0
        i = 0
        # Handle possible leading minus sign
        if s[0] == '-':
            # digit sum is first digit negated, then add rest digits
            # e.g. -12 -> -(1) + 2 = -1 + 2 = 1
            total -= int(s[1])
            i = 2
        else:
            i = 0
        while i < len(s):
            total += int(s[i])
            i += 1
        return total

    # Sort by digit_sum, stable so original order kept if tie
    return sorted(nums, key=digit_sum)
